usage:
package main

import (
	"context"
	"fmt"
	"os"

	"github.com/example/extensionsdemo"
	"github.com/example/extensionsdemo/option"
)

func main() {
	client := extensionsdemo.NewClient(
		option.WithAPIKey(os.Getenv("EXTENSIONSDEMO_API_KEY")),
	)
	result, err := client.Catalog.Browse(context.TODO())
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
